const apiError = (status: number) =>
  new OpenAI.APIError(status, undefined, `status ${status}`, new Headers());

const instantRetry: RetryPolicy = {
  attempts: 3,
  baseDelayMs: 0,
  maxDelayMs: 0,
  sleep: async () => {},
};

type Outcome = 'ok' | 'fail' | Error | { content: string };

function fakeClient(behavior: Record<string, Outcome | Outcome[]>) {
  const calls: string[] = [];
  const seq: Record<string, number> = {};
  const factory = (ep: LLMEndpoint) =>
    ({
      chat: {
        completions: {
          create: async () => {
            calls.push(ep.baseURL);
            const b = behavior[ep.baseURL];
            const i = seq[ep.baseURL] ?? 0;
            seq[ep.baseURL] = i + 1;
            const outcome = Array.isArray(b) ? b[Math.min(i, b.length - 1)] : b;
            if (outcome === 'fail') throw apiError(401);
            if (outcome instanceof Error) throw outcome;
            return {
              choices: [
                {
                  message: {
                    content:
                      typeof outcome === 'object' && outcome !== null
                        ? outcome.content
                        : `translated via ${ep.baseURL}`,
                  },
                },
              ],
            };
          },
        },
      },
    }) as unknown as Pick<OpenAI, 'chat'>;
  return { calls, factory };
}

